# frozen_string_literal: true

def school_download_icon
  '<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4" stroke-linecap="round" stroke-linejoin="round"/></svg>'
end

def university_explorer_markup
  data = JSON.parse(File.read('_data/university-calendars.json'))
  media = JSON.parse(File.read('_data/university-card-images.json')).fetch('photos')
  cards = data.fetch('stateUniversities').map do |institution|
    calendars = data.fetch('calendars').select { |item| item['id'] == institution['calendarId'] || item['id'].start_with?(institution['id'] + '-') }
    photo = calendars.find { |item| item['photo'] }&.fetch('photo') || institution['photo']
    image = photo && media.find { |item| item['source'] == photo['src'] }
    illustration = if image
      %(<figure class="school-campus#{photo['kind']=='emblem' ? ' school-campus--emblem' : ''}"><img src="#{h(image['src'])}" srcset="#{h(image['srcset'])}" sizes="(max-width:650px) calc(100vw - 36px), (max-width:1050px) 45vw, 420px" alt="#{h(photo['alt'])}" width="#{image['width']}" height="#{image['height']}" loading="lazy" decoding="async"><figcaption><a href="#{h(photo['pageUrl'])}" target="_blank" rel="noopener">#{h(photo['author'])}</a> · <a href="#{h(photo['licenseUrl'])}" target="_blank" rel="noopener">#{h(photo['license'])}</a></figcaption></figure>)
    else
      %(<div class="school-campus school-campus--identity"><span>#{ui_icon('school')}</span><strong>#{h(institution['name'])}</strong><a href="#{h(institution['url'])}" target="_blank" rel="noopener">Augstskolas oficiālā vietne ↗</a></div>)
    end
    variants = calendars.each_with_index.map do |calendar, index|
      rows = calendar.fetch('events').map do |event|
        kind = { 'holiday'=>'Brīvlaiks / brīvdiena', 'study'=>'Studiju periods', 'exam'=>'Sesija / pārbaudījumi', 'registration'=>'Reģistrācija' }.fetch(event['kind'])
        ending = event['end'] && event['end'] != event['start'] ? " – #{Date.parse(event['end']).strftime('%d.%m.%Y.') }" : ''
        %(<li class="school-uni-event school-uni-event--#{event['kind']}" data-uni-event-kind="#{event['kind']}"><span>#{kind}</span><strong>#{h(event['label'])}</strong><time datetime="#{event['start']}">#{Date.parse(event['start']).strftime('%d.%m.%Y.')}#{ending}</time>#{event['scope'] ? "<small>#{h(event['scope'])}</small>" : ''}</li>)
      end.join
      %(<div data-uni-variant="#{calendar['id']}"#{index.zero? ? '' : ' hidden'}><p class="school-uni-scope">#{h(calendar['scope'])}</p><ul class="school-uni-events">#{rows}</ul><p class="school-uni-filter-empty" hidden>Šajā grafikā atlasītajam perioda veidam nav publicētu datumu.</p><div class="school-uni-actions"><a href="#{h(calendar['source']['url'])}" target="_blank" rel="noopener">Oficiālais kalendārs ↗</a><button type="button" data-uni-export="#{calendar['id']}">#{school_download_icon} Kalendārs · ICS</button></div></div>)
    end.join
    if calendars.empty?
      confirmed = institution.fetch('confirmedDates', []).map { |event| %(<li><time datetime="#{event['start']}">#{Date.parse(event['start']).strftime('%d.%m.%Y.')}</time>#{h(event['label'])}</li>) }.join
      variants = %(<p class="school-uni-scope">Publisks 2026./2027. studiju gada brīvlaiku grafiks pārbaudītajos avotos nav atrasts. Datumus precizē augstskolā.</p><details><summary>Apstiprinātie ievadpasākumi</summary><ul class="school-confirmed-dates">#{confirmed}</ul><p>Tie ir studiju uzsākšanas datumi, nevis brīvlaiks.</p><a href="#{h(institution['dateSource']['url'])}" target="_blank" rel="noopener">Publisko datumu avots ↗</a></details>)
    end
    picker = calendars.length > 1 ? %(<label class="school-uni-variant-label">Grafiks<select data-uni-variant-picker>#{calendars.map { |calendar| %(<option value="#{calendar['id']}">#{h(calendar['id'].end_with?('doctoral') ? 'Doktorantūras skola' : calendar['variantLabel'] || 'Vispārējais grafiks')}</option>) }.join}</select></label>) : ''
    %(<article class="school-uni-card" id="study-#{institution['id']}" data-university="#{institution['id']}" data-uni-verified="#{!calendars.empty?}" data-uni-search="#{h(institution['name']+' '+institution['city']+' '+institution['id'])}">#{illustration}<div class="school-uni-body"><div class="school-uni-meta"><span>#{ui_icon('pin')} #{h(institution['city'])}</span><span>2026 / 27</span></div><h3>#{h(institution['name'])}</h3><span class="school-uni-status#{calendars.empty? ? ' is-pending' : ''}">#{calendars.empty? ? 'Brīvlaiku grafiks nav publicēts' : 'Oficiālā avota datumi'}</span>#{picker}#{variants}</div></article>)
  end.join
  payload = JSON.generate(data).gsub('<','\\u003c')
  %(<section class="school-universities" id="augstskolas" data-university-explorer aria-labelledby="school-uni-title"><div class="school-section-heading"><div><span class="hub-kicker">STUDENTIEM · 2026 / 27</span><h2 id="school-uni-title">Augstskolas. Katram savs grafiks.</h2><p>11 valsts augstskolas no IZM saraksta. Semestri, sesijas un brīvlaiki ir norādīti atsevišķi; katras programmas grafiks var atšķirties.</p></div><a href="/studiju-kalendars/">Studiju kalendāra pārskats ↗</a></div><div class="school-uni-toolbar"><label>Augstskola<select data-uni-choice><option value="all">Visas augstskolas</option>#{data['stateUniversities'].map { |item| %(<option value="#{item['id']}">#{h(item['name'])}</option>) }.join}</select></label><label>Meklēt augstskolu vai pilsētu<input type="search" data-uni-search-input placeholder="Piemēram, Jelgava vai LU"></label><label>Perioda veids<select data-uni-kind><option value="all">Visi periodi</option><option value="holiday">Brīvlaiki un brīvdienas</option><option value="study">Studiju periodi</option><option value="exam">Sesijas un pārbaudījumi</option><option value="registration">Reģistrācija</option></select></label><label class="school-uni-check"><input type="checkbox" data-uni-verified-only> Tikai ar publicētu grafiku</label></div><p class="school-uni-result" data-uni-result role="status">Parādītas 11 augstskolas</p><div class="school-uni-grid">#{cards}</div><p class="school-empty" data-uni-empty hidden>Neviena augstskola neatbilst meklējumam. Maini nosaukumu vai filtrus.</p><aside class="school-uni-note"><strong>Sesija ir studiju pienākumu laiks.</strong><p>Eksāmenu periodu nedrīkst uzskatīt par brīvlaiku. Ja avots nenosaka vienotu brīvlaika termiņu, datumus neizsecinām. LU doktorantūrai ir atsevišķs grafiks. Privātās augstskolas, koledžas un aktuālais iestāžu statuss: <a href="#{h(data['directorySource']['registerUrl'])}" target="_blank" rel="noopener">AIKA reģistrs ↗</a>.</p><p><a href="#{h(data['directorySource']['url'])}" target="_blank" rel="noopener">IZM valsts augstskolu saraksts ↗</a> · <a href="/pilsetas-un-fotografijas/#university-photo-lu">Fotogrāfiju avoti un licences</a></p></aside><script type="application/json" data-university-data>#{payload}</script></section>)
end

def school_hub_markup
  school = LATVIA_VERIFIED.fetch('education').fetch('school').merge('end'=>'2027-08-31')
  source = LATVIA_VERIFIED['sources'].find { |item| item['id'] == school['sourceId'] }
  occasions = JSON.parse(File.read('_data/occasions.json'))
  photos = [CITIES.find { |city| city['id']=='preili' }['photo'], occasions.find { |item| item.dig('photo','id')=='winter' }['photo'], CITIES.find { |city| city['id']=='iecava' }['photo'], occasions.find { |item| item.dig('photo','id')=='summer' }['photo']]
  school['breaks'] = school['breaks'].each_with_index.map { |item,index| item.merge('id'=>%w[autumn winter spring summer][index]) }
  cards = school['breaks'].each_with_index.map do |item,index|
    photo = photos[index];media=school_card_media.find { |image| image['source']==photo['src'] };days=(Date.parse(item['end'])-Date.parse(item['start'])).to_i+1
    %(<article class="hub-school-break" id="brivlaiks-#{item['id']}" data-school-break="#{item['id']}" data-start="#{item['start']}" data-end="#{item['end']}"><div class="hub-school-photo"><img src="#{h(media['src'])}" srcset="#{h(media['srcset'])}" sizes="#{h(media['sizes'])}" alt="#{h(photo['alt'])}" width="#{media['width']}" height="#{media['height']}" loading="lazy" decoding="async"><span>#{%w[RUDENS ZIEMA PAVASARIS VASARA][index]}</span><button class="school-save" type="button" data-school-save="#{item['id']}" aria-pressed="false" aria-label="Saglabāt: #{h(item['label'])}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg></button></div><div class="hub-school-break-copy"><h3>#{h(item['label'])}</h3><time datetime="#{item['start']}">#{hub_date(item['start'])} – #{hub_date(item['end'])}</time><small>#{h(item['scope'] || '1.–12. klasei')}</small><div class="school-break-duration"><strong>#{days}</strong><span>kalendārās dienas</span><button type="button" data-school-export="#{item['id']}" aria-label="Lejupielādēt: #{h(item['label'])}">#{school_download_icon} ICS</button></div><p>Ilustratīvs attēls · <a href="#{h(photo['sourceUrl'])}" target="_blank" rel="noopener">#{h(photo['author'])} · #{h(photo['license'])} ↗</a></p></div></article>)
  end.join
  current=Date.today;current=Date.new(2026,9,1) unless (Date.new(2026,9,1)..Date.new(2027,8,31)).cover?(current)
  month_choices=(0...12).map { |offset| date=Date.new(2026,9,1)>>offset; %(<option value="#{date.strftime('%Y-%m')}"#{date.month==current.month&&date.year==current.year ? ' selected' : ''}>#{MONTHS[date.month-1].capitalize} #{date.year}</option>) }.join
  future = [['2027-28','2027./2028.'],['2028-29','2028./2029.'],['2029-30','2029./2030.'],['2030-31','2030./2031.']].map { |slug,label| %(<a href="/skolas-brivlaiki/#{slug}/"><strong>#{label}</strong><span>Oficiālie datumi vēl nav publicēti</span><span aria-hidden="true">↗</span></a>) }.join
  payload=JSON.generate({'school'=>school,'holidays'=>HOLIDAYS.select { |day| day['date']>=school['start']&&day['date']<=school['end']&&day['dayOff'] },'source'=>source}).gsub('<','\\u003c')
  <<~HTML
  <div class="hub-page school-experience" data-school-experience>
    <div class="school-opening"><div><span class="hub-kicker">PLĀNS VISAM MĀCĪBU GADAM</span><h2>Mazāk minējumu. Vairāk laika kopā.</h2><p>Izvēlies klasi, apskati oficiālos brīvlaikus un saglabā datumus savā kalendārā.</p><div class="school-opening-actions"><a href="#skolenu-brivlaiki">Skolēnu brīvlaiki ↓</a><a href="#augstskolas">Augstskolu kalendāri ↓</a><button type="button" data-school-export="all">#{school_download_icon} Saglabāt kalendārā</button></div></div><aside class="school-next" data-school-next><span>NĀKAMAIS BRĪVLAIKS</span><strong>Ziemas brīvdienas</strong><time datetime="2026-12-21">21.12.2026. – 01.01.2027.</time><b data-school-next-count></b></aside></div>
    <nav class="school-jump-links" aria-label="Skolas kalendāra sadaļas"><a href="#skolenu-brivlaiki">Brīvlaiki</a><a href="#macibu-kalendars">Mēneša kalendārs</a><a href="#augstskolas">Augstskolas</a><a href="#brivo-dienu-plans">Brīvo dienu plāns</a><a href="#skolas-avoti">Avoti un jautājumi</a></nav>
    <section class="school-explorer" id="skolenu-brivlaiki" aria-labelledby="school-breaks-title"><div class="school-section-heading"><div><span class="hub-kicker">LATVIJAS SKOLĒNIEM</span><h2 id="school-breaks-title">Tavai klasei atbilstošs brīvlaiks</h2><p>Vispārējās pamatizglītības un vidējās izglītības programmu datumi.</p></div><span class="school-official-badge">MK noteikumi Nr. 768</span></div><div class="school-selection"><label>Mācību gads<select data-school-year><option value="2026-27">2026./2027. · publicēts</option><option value="2027-28">2027./2028. · nav publicēts</option><option value="2028-29">2028./2029. · nav publicēts</option><option value="2029-30">2029./2030. · nav publicēts</option><option value="2030-31">2030./2031. · nav publicēts</option></select></label><label>Klase<select data-school-class>#{(1..12).map { |grade| %(<option value="#{grade}"#{grade==8 ? ' selected' : ''}>#{grade}. klase</option>) }.join}</select></label><div class="school-class-end"><span>Mācību gada beigas</span><strong data-school-end>2027. gada 31. maijs</strong></div><label class="school-saved-filter"><input type="checkbox" data-school-saved-only> Saglabātie <b data-school-saved-count>0</b></label></div><p class="school-local-note" data-school-grade-note>1.–8. un 10.–11. klasei vasaras brīvdienas sākas 1. jūnijā. Reģionu izvēle nav vajadzīga: noteikumos ir vienots Latvijas pamatgrafiks.</p><p class="school-pending-message" data-school-pending hidden>Šim mācību gadam oficiālie datumi vēl nav publicēti. Iepriekšējā gada datumus nepārceļam.</p><div class="hub-school-grid" data-school-break-grid>#{cards}</div><p class="school-empty" data-school-empty hidden>Šai izvēlei saglabātu brīvlaiku vēl nav. Atzīmē kartīti ar sirsniņu.</p></section>
    <section class="school-month-section" id="macibu-kalendars" aria-labelledby="school-calendar-title"><div class="school-section-heading"><div><span class="hub-kicker">VISS MĒNESIS VIENĀ SKATĀ</span><h2 id="school-calendar-title">Mācību un atpūtas dienas</h2><p>Spied uz datuma, lai redzētu tā statusu izvēlētajai klasei.</p></div><button type="button" data-school-print>#{ui_icon('print')} Drukāt kalendāru</button></div><div class="school-calendar-layout"><div class="school-month"><div class="school-month-nav"><button type="button" data-school-month-step="-1" aria-label="Iepriekšējais mēnesis">←</button><label><span class="sr-only">Mēnesis</span><select data-school-month>#{month_choices}</select></label><button type="button" data-school-month-step="1" aria-label="Nākamais mēnesis">→</button><button type="button" data-school-today>Šodien</button></div><div class="school-weekdays" aria-hidden="true">#{%w[P O T C Pk S Sv].map { |day| "<span>#{day}</span>" }.join}</div><div class="school-month-grid" data-school-month-grid></div><div class="school-calendar-legend"><span class="legend-break">Brīvlaiks</span><span class="legend-holiday">Svētku brīvdiena</span><span class="legend-weekend">Nedēļas nogale</span></div></div><aside class="school-date-detail" data-school-day-detail aria-live="polite"><span class="hub-kicker">IZVĒLĒTAIS DATUMS</span><h3>Izvēlies dienu kalendārā</h3><p>Brīvlaiki un svētku brīvdienas tiek rādīti atsevišķi.</p></aside></div><noscript><p>Ieslēdz JavaScript, lai izmantotu klikšķināmo kalendāru. Visi oficiālie brīvlaiki ir lasāmi kartītēs augstāk.</p></noscript></section>
    #{university_explorer_markup}
    <section class="school-planner" id="brivo-dienu-plans" aria-labelledby="school-planner-title"><div><span class="hub-kicker">ĢIMENES PLĀNOŠANAI</span><h2 id="school-planner-title">Cik dienu bez regulārām mācībām?</h2><p>Skaita abas robeždienas, nedēļas nogales, valsts svētku brīvdienas un izvēlētās klases oficiālo brīvlaiku. Viena diena netiek ieskaitīta divreiz.</p></div><form data-school-counter><label>No<input type="date" name="from" value="2026-12-19" min="2026-09-01" max="2027-08-31" required></label><label>Līdz<input type="date" name="to" value="2027-01-03" min="2026-09-01" max="2027-08-31" required></label><button type="submit">Aprēķināt dienas</button><output data-school-counter-result aria-live="polite"></output></form><p class="school-counter-note">Skolas noteiktā 1. klases papildu nedēļa, pārceltas mācību dienas, izlaiduma klašu eksāmeni un individuāli grafiki jāņem vērā atsevišķi.</p></section>
    <section class="school-sources" id="skolas-avoti" aria-labelledby="school-sources-title"><span class="hub-kicker">AVOTI UN ATBILDES</span><h2 id="school-sources-title">Pareizs datums sākas ar avotu.</h2><p>Skolu datumi pārbaudīti 10.11.2026. <a href="#{h(source['url'])}" target="_blank" rel="noopener">Ministru kabineta noteikumi Nr. 768 ↗</a>. Seko arī savas skolas paziņojumiem.</p><details><summary>Vai Latvijā brīvlaiks atšķiras pa reģioniem?</summary><p>Šajos noteikumos vispārējai pamatizglītībai un vidējai izglītībai ir vienots valsts pamatgrafiks. 1. klases papildu brīvdienu nedēļu otrajā semestrī nosaka skola. Neparedzētu būtisku mācību pārtraukumu dēļ iespējams noteikumos paredzēts mācību gada pagarinājums.</p></details><details><summary>Kādi ir 9. un 12. klases izņēmumi?</summary><p>9. klasei mācību gads beidzas 2027. gada 11. jūnijā, 12. klasei – 18. jūnijā. Vasaras brīvlaiks no 1. jūnija līdz 31. augustam noteikumos attiecas uz 1.–8. un 10.–11. klasi. Eksāmenu pienākumus pārbaudi atsevišķi.</p></details><details><summary>Vai skolēnu brīvlaiks attiecas arī uz augstskolām?</summary><p>Nē. Augstskolas publicē savus grafikus; sesijas un studiju periodi nav brīvlaiks. Programmas izņēmums ir norādīts pie attiecīgā notikuma vai avotā.</p></details><details><summary>Kā lietot ICS kalendāra failu?</summary><p>Failu var importēt Google Calendar, Apple Calendar vai Outlook. Tas ir vienreizējs datumu imports; avota izmaiņas jau importētā failā neatjaunojas automātiski. Saglabātās sirsniņas paliek tikai šajā pārlūkā.</p></details><details><summary>Kas redzams nākamajiem mācību gadiem?</summary><p>Neizziņotu gadu datumi nav aprēķināti no iepriekšējiem gadiem. Izvēloties nepublicētu gadu, brīvlaiku kartītes un aprēķini ir paslēpti.</p></details><a href="/pilsetas-un-fotografijas/">Fotogrāfiju autori un licences ↗</a></section>
    <section class="hub-section"><div class="hub-section-head"><h2>Nākamie mācību gadi</h2></div><div class="hub-school-future">#{future}</div></section>
    <nav class="hub-related" aria-label="Saistītie mācību kalendāri"><a href="/skolas-kalendars/"><strong>Skolas kalendārs</strong><span>Semestri un mācību gada datumi ↗</span></a><a href="/valsts-parbaudes-darbi/"><strong>Valsts pārbaudes darbi</strong><span>Eksāmenu un monitoringa grafiks ↗</span></a><a href="/stundu-saraksts/"><strong>Stundu saraksts</strong><span>Izveido savu nedēļas plānu ↗</span></a></nav>
    <p class="school-feedback" data-school-feedback role="status"></p><script type="application/json" data-school-data>#{payload}</script>
  </div>
  HTML
end
